# 下向き最適化のパレートフロントを抽出する関数
def extract_pareto_front(points):
    """
    与えられた点集合から下向き最適化のパレートフロントを抽出する
    （両方の目的関数について小さい値が良い解と仮定）
    
    Args:
        points: 評価値の行列 (n個の解 × 2つの目的関数値)
    
    Returns:
        パレートフロントの点のみを含む配列
    """
    n_points = len(points)
    is_pareto = np.ones(n_points, dtype=bool)  # 初期状態ではすべての点がパレートフロント候補
    
    for i in range(n_points):
        # 点iが他の点によって支配されているかチェック
        for j in range(n_points):
            if i != j:
                # 点jが点iを支配しているかチェック
                # (jのすべての目的関数値がi以下で、少なくとも1つは厳密に小さい)
                if np.all(points[j] <= points[i]) and np.any(points[j] < points[i]):
                    is_pareto[i] = False  # 点iはパレートフロントではない
                    break
    
    return points[is_pareto]

# 重複を削除する関数
def remove_duplicates(points):
    """
    解集合から重複した解を削除する
    
    Args:
        points: 評価値の行列 (n個の解 × 2つの目的関数値)
    
    Returns:
        重複を削除した評価値の行列
    """
    # 文字列化して一意なタプルを抽出
    points_tuple = [tuple(p) for p in points]
    unique_tuples = set(points_tuple)
    
    # 重複のない配列を返す
    return np.array(list(unique_tuples))

# クラウディングディスタンスの計算関数
def calculate_crowding_distance(points):
    """
    パレートフロント上の点集合のクラウディングディスタンスを計算する
    
    Args:
        points: 評価値の行列 (n個の解 × 2つの目的関数値)
    
    Returns:
        各解のクラウディングディスタンス値の配列
    """
    n_points, n_objectives = points.shape
    if n_points <= 2:
        return np.full(n_points, np.inf)  # 2つ以下の点の場合、無限大を返す
    
    # 初期化
    distances = np.zeros(n_points)
    
    for obj in range(n_objectives):
        # 目的関数値でソート
        sorted_indices = np.argsort(points[:, obj])
        sorted_values = points[sorted_indices, obj]
        
        # 端点は無限大に設定
        distances[sorted_indices[0]] = np.inf
        distances[sorted_indices[-1]] = np.inf
        
        # 値の範囲を計算（正規化のため）
        value_range = sorted_values[-1] - sorted_values[0]
        if value_range == 0:
            continue  # すべての値が同じ場合はスキップ
        
        # 中間点のクラウディングディスタンスを計算
        for i in range(1, n_points - 1):
            distances[sorted_indices[i]] += (sorted_values[i+1] - sorted_values[i-1]) / value_range
    
    return distances

# ハイパーボリュームの計算関数
def calculate_hypervolume(points, reference_point):
    """
    パレートフロント上の点集合のハイパーボリュームを計算する
    
    Args:
        points: 評価値の行列 (n個の解 × 2つの目的関数値)
        reference_point: 参照点（原点よりも悪い点）
    
    Returns:
        ハイパーボリューム値
    """
    # 最小化問題を仮定
    # 参照点よりも優れている点のみを選択
    valid_points = points[np.all(points <= reference_point, axis=1)]
    if len(valid_points) == 0:
        return 0.0
    
    # 目的関数1でソート
    sorted_points = valid_points[np.argsort(valid_points[:, 0])]
    
    # 計算
    hv = 0.0
    prev_x = reference_point[0]
    for i in range(len(sorted_points)):
        point = sorted_points[i]
        if i == 0:
            prev_y = reference_point[1]
        else:
            prev_y = min(prev_y, sorted_points[i-1, 1])
        
        # 面積を加算
        width = prev_x - point[0]
        height = prev_y - point[1]
        if width > 0 and height > 0:
            hv += width * height
        prev_x = point[0]
    
    return hv

# ジニ係数の計算関数
def calculate_gini_coefficient(points):
    """
    パレートフロント上の点集合のジニ係数を計算する
    
    Args:
        points: 評価値の行列 (n個の解 × 2つの目的関数値)
    
    Returns:
        ジニ係数（0-1の値、0が完全に均一、1が完全に不均一）
    """
    # 点間の距離を計算
    if len(points) <= 1:
        return 0.0  # 1点しかない場合はジニ係数は0
    
    # ユークリッド距離を計算
    distances = pdist(points, 'euclidean')
    # 距離行列に変換
    distance_matrix = squareform(distances)
    
    # 各点の近傍点との平均距離を計算
    mean_distances = np.mean(distance_matrix, axis=1)
    
    # mean_distancesが全て0の場合は、すべての点が同じ位置にあるため、ジニ係数は0
    if np.all(mean_distances == 0):
        return 0.0
    
    # ジニ係数の計算
    # まずデータをソート
    sorted_distances = np.sort(mean_distances)
    n = len(sorted_distances)
    
    # 累積和を計算
    cumsum = np.cumsum(sorted_distances)
    
    # ローレンツ曲線の下の面積を計算
    lorenz_area = np.sum(cumsum) / (n * np.sum(sorted_distances))
    
    # ジニ係数 = 1 - 2 * ローレンツ曲線の下の面積
    gini = 1 - 2 * lorenz_area
    
    return gini

# 指標の計算と表示
def calculate_and_display_metrics(pareto_sets, names):
    print("=== パレートフロントの質評価指標 ===")
    
    # 重複を削除したデータセットを作成
    unique_pareto_sets = []
    for points in pareto_sets:
        unique_points = remove_duplicates(points)
        unique_pareto_sets.append(unique_points)
    
    # 参照点の設定（すべての点より悪い値を使用）
    max_cost = max([np.max(p[:, 0]) for p in unique_pareto_sets]) * 1.1
    max_makespan = max([np.max(p[:, 1]) for p in unique_pareto_sets]) * 1.1
    reference_point = np.array([max_cost, max_makespan])
    
    # 各指標の計算
    for i, (points, unique_points, name) in enumerate(zip(pareto_sets, unique_pareto_sets, names)):
        # 重複率を計算
        duplicate_rate = (len(points) - len(unique_points)) / len(points) * 100 if len(points) > 0 else 0
        
        # クラウディングディスタンス
        cd = calculate_crowding_distance(unique_points)
        avg_cd = np.mean(cd[~np.isinf(cd)]) if np.any(~np.isinf(cd)) else np.inf
        
        # ハイパーボリューム
        hv = calculate_hypervolume(unique_points, reference_point)
        
        # ジニ係数
        gini = calculate_gini_coefficient(unique_points)
        
        print(f"\n{name}:")
        print(f"  解の数: {len(points)} (重複削除後: {len(unique_points)}, 重複率: {duplicate_rate:.1f}%)")
        print(f"  平均クラウディングディスタンス: {avg_cd:.4f}")
        print(f"  ハイパーボリューム: {hv:.4f}")
        print(f"  ジニ係数: {gini:.4f}")

    return unique_pareto_sets  # 重複を削除したデータセットを返す

